text:
The diff deletes `return n * y;` from the years group of the `switch` in `parse()`. Because there is no `break`, the year cases (`'years'`, `'year'`, `'yrs'`, `'yr'`, `'y'`) now fall through to the weeks case and return `n * w`. So `ms('1y')` returns `604800000` (one week) instead of `31557600000` (365.25 days). This is directly observable by any caller who parses year strings, so the change is a real behavioural break, not an equivalent refactor.

```json
{"defect": true, "testFile": {"path": "proof-test.js", "content": "var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('parses year units as 365.25 days each', function () {
    assert.strictEqual(ms('1y'), 31557600000);
    assert.strictEqual(ms('1year'), 31557600000);
    assert.strictEqual(ms('2yrs'), 63115200000);
    assert.strictEqual(ms('-1y'), -31557600000);
    // weeks remain unaffected by the fall-through
    assert.strictEqual(ms('1w'), 604800000);
  });
});
"}, "note": "Removing `return n * y;` makes the year cases fall through to the weeks case, so ms('1y') now returns 604800000 (one week) instead of 31557600000 (365.25 days). The test asserts the correct year parsing and fails on the patched build."}
```

